// ── Parse Slack Interactive Payload ─────────────────────────────────────
const rawBody = $input.first().json.body;
let slackPayload;

if (typeof rawBody === 'string') {
  const decoded = decodeURIComponent(rawBody.replace(/^payload=/, ''));
  slackPayload = JSON.parse(decoded);
} else if (rawBody && rawBody.payload) {
  slackPayload = typeof rawBody.payload === 'string'
    ? JSON.parse(rawBody.payload)
    : rawBody.payload;
} else {
  slackPayload = rawBody || {};
}

const action = slackPayload.actions?.[0] || {};
const actionId = action.action_id || 'unknown';
const actionValue = action.value || '{}';
const responseUrl = slackPayload.response_url;
const userName = slackPayload.user?.name || slackPayload.user?.username || 'Bạn';
const userId = slackPayload.user?.id || 'U_UNKNOWN';

let parsedValue = {};
try { parsedValue = JSON.parse(actionValue); } catch(e) {}

let replyMessage = `✅ Đã ghi nhận thao tác của @${userName}`;
let dbQuery = '';
let triggerCampaignWebhook = false;
let publishToFacebook = false;
let campaignId = parsedValue.campaign_id || null;
let targetOpportunityId = parsedValue.opportunity_id || null;
let directPostContent = parsedValue.post_content || '';

if (actionId === 'skip') {
  replyMessage = `⏭️ *Đã bỏ qua bài viết này.* — bởi @${userName}`;
} else if (actionId === 'approve_ad_campaign') {
  const campName = parsedValue.name || 'Bài viết Marketing';
  replyMessage = `🚀 *ĐÃ DUYỆT & ĐANG TỰ ĐỘNG ĐĂNG BÀI LÊN FACEBOOK:* [${campName}]\n> 👤 *Phê duyệt bởi:* @${userName} vào lúc ${new Date().toLocaleTimeString('vi-VN')}`;
  publishToFacebook = true;
  if (campaignId) {
    dbQuery = `UPDATE campaigns SET status = 'PUBLISHED', approved_by = '${userName}', approved_at = CURRENT_TIMESTAMP WHERE id = '${campaignId}';`;
  }
} else if (actionId === 'reject_ad_campaign') {
  const campName = parsedValue.name || 'Bài viết Marketing';
  replyMessage = `❌ *ĐÃ TỪ CHỐI BÀI VIẾT:* [${campName}] — bởi @${userName}`;
  if (campaignId) {
    dbQuery = `UPDATE campaigns SET status = 'REJECTED' WHERE id = '${campaignId}';`;
  }
} else if (actionId === 'claim_lead') {
  replyMessage = `🤝 *Lead đã được nhận phụ trách bởi:* @${userName}`;
} else if (actionId === 'book_meeting') {
  replyMessage = `📅 *Đã chuyển trạng thái Đặt lịch tư vấn (Book Meeting) bởi:* @${userName}`;
} else if (actionId === 'create_campaign_for_opportunity' || actionId === 'create_content_for_opportunity') {
  replyMessage = `⚡ *Đang tạo Bài viết Marketing & Đề xuất Chiến dịch cho Cơ hội này...* (Yêu cầu bởi @${userName})`;
  triggerCampaignWebhook = true;
}

return [{
  json: {
    action_id: actionId,
    response_url: responseUrl,
    user_name: userName,
    user_id: userId,
    reply_message: replyMessage,
    db_query: dbQuery,
    parsed_value: parsedValue,
    trigger_campaign_webhook: triggerCampaignWebhook,
    publish_to_facebook: publishToFacebook,
    campaign_id: campaignId,
    direct_post_content: directPostContent,
    opportunity_id: targetOpportunityId
  }
}];

const dbData = $input.first()?.json || {};
const parsedContext = $('Parse Slack Action').first()?.json || {};

const contentToPost = dbData.post_content || dbData.fb_content || dbData.var_a || parsedContext.direct_post_content || '🚀 Thiết kế Website chuẩn quốc tế cùng S.T.A.R.K\n\n📁 Portfolio chính thức: https://company-plum-rho.vercel.app/\n📞 Hotline/Zalo: 0845.663.357';

return [{
  json: {
    postText: contentToPost
  }
}];

